﻿Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()
$ErrorActionPreference = "SilentlyContinue"

try { Set-PSReadLineOption -HistorySaveStyle SaveNothing } catch {}

Clear-History

try {
    $historyPath = (Get-PSReadLineOption).HistorySavePath
    if ($null -ne $historyPath -and (Test-Path $historyPath)) {
        Remove-Item -Path $historyPath -Force -ErrorAction SilentlyContinue
    }
} catch {}

function Ensure-Admin {
    $wp = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    if (-not $wp.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe"
        $psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -STA -File `"$PSCommandPath`""
        $psi.Verb = "runas"
        try { [Diagnostics.Process]::Start($psi) | Out-Null } catch {}
        exit
    }
}

function AddOrSet-Reg([string]$path,[string]$name,[string]$type,[string]$value) {
    & reg.exe add $path /v $name /t $type /d $value /f | Out-Null
}

function Get-RegValue([string]$psPath,[string]$name) {
    try {
        return (Get-ItemProperty -Path $psPath -Name $name -ErrorAction Stop).$name
    } catch {
        return $null
    }
}

function Remove-RegValue([string]$psPath,[string]$name) {
    try { Remove-ItemProperty -Path $psPath -Name $name -ErrorAction SilentlyContinue } catch {}
}

function Get-NetshValue([string]$label) {
    $out = & netsh int tcp show global
    foreach ($line in $out) {
        if ($line -match [regex]::Escape($label)) {
            return (($line -split ":")[1]).Trim()
        }
    }
    return ""
}

function Get-ServiceStopped([string]$svc) {
    $txt = & sc.exe query $svc | Out-String
    return ($txt -match "STATE\s*:\s*\d+\s+STOPPED")
}

function Get-IPv4DnsState {
    try {
        $a = Get-NetAdapter | Where-Object {$_.Status -eq 'Up'} | Select-Object -First 1
        if (-not $a) { return @(-1, "") }
        $dns = (Get-DnsClientServerAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv4).ServerAddresses
        return @($a.ifIndex, ($dns -join ','))
    } catch {
        return @(-1, "")
    }
}

$script:BackupFile = Join-Path $env:TEMP "Tuaperd Fanphu_backup.json"

function Save-Backup {
    $dns = Get-IPv4DnsState
    $obj = [ordered]@{
        AutoTuning = Get-NetshValue "Receive Window Auto-Tuning Level"
        ECN = Get-NetshValue "ECN Capability"
        RSS = Get-NetshValue "Receive-Side Scaling State"
        Timestamps = Get-NetshValue "RFC 1323 Timestamps"
        InitialRto = Get-NetshValue "Initial RTO"
        SysMainStopped = Get-ServiceStopped "sysmain"
        DnsIfIndex = $dns[0]
        DnsServers = $dns[1]

        TcpTimedWaitDelay = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpTimedWaitDelay"
        MaxUserPort = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "MaxUserPort"
        TcpMaxDataRetransmissions = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpMaxDataRetransmissions"
        Tcp1323Opts = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "Tcp1323Opts"
        NetworkThrottlingIndex = Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NetworkThrottlingIndex"
        SystemResponsiveness = Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness"
        KeyboardDataQueueSize = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" "KeyboardDataQueueSize"
        MouseDataQueueSize = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" "MouseDataQueueSize"
        KeyboardDelay = Get-RegValue "HKCU:\Control Panel\Keyboard" "KeyboardDelay"
        KeyboardSpeed = Get-RegValue "HKCU:\Control Panel\Keyboard" "KeyboardSpeed"
        MouseSpeed = Get-RegValue "HKCU:\Control Panel\Mouse" "MouseSpeed"
        MouseThreshold1 = Get-RegValue "HKCU:\Control Panel\Mouse" "MouseThreshold1"
        MouseThreshold2 = Get-RegValue "HKCU:\Control Panel\Mouse" "MouseThreshold2"
        MenuShowDelay = Get-RegValue "HKCU:\Control Panel\Desktop" "MenuShowDelay"
        WaitToKillServiceTimeout = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Control" "WaitToKillServiceTimeout"
        HiberbootEnabled = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "HiberbootEnabled"
        SearchOrderConfig = Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "SearchOrderConfig"
        GameDVR = Get-RegValue "HKLM:\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR" "value"
        ForceIdle = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "ForceIdle"
        IdleUsbSelectiveSuspend = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "IdleUsbSelectiveSuspend"
        SelectiveSuspendEnabled = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "SelectiveSuspendEnabled"
        DisableSelectiveSuspend = Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\USB" "DisableSelectiveSuspend"

        Policy_NonBestEffortLimit = Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched" "NonBestEffortLimit"
        Policy_DODownloadMode = Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" "DODownloadMode"
        Policy_LetAppsRunInBackground = Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" "LetAppsRunInBackground"
    }
    ($obj | ConvertTo-Json -Depth 4) | Set-Content -Path $script:BackupFile -Encoding UTF8
}

function Restore-Reg($psPath,$regPath,$name,$type,$value) {
    if ($null -eq $value) {
        Remove-RegValue $psPath $name
    } else {
        & reg.exe add $regPath /v $name /t $type /d $value /f | Out-Null
    }
}

function Restore-Backup {
    if (-not (Test-Path $script:BackupFile)) { return $false }
    $b = Get-Content $script:BackupFile -Raw | ConvertFrom-Json

    if ($b.AutoTuning) {
        $v = $b.AutoTuning.ToLower()
        if ($v -like "*normal*") { & netsh int tcp set global autotuninglevel=normal | Out-Null }
        elseif ($v -like "*restricted*") { & netsh int tcp set global autotuninglevel=restricted | Out-Null }
        elseif ($v -like "*highly*") { & netsh int tcp set global autotuninglevel=highlyrestricted | Out-Null }
        else { & netsh int tcp set global autotuninglevel=disabled | Out-Null }
    }
    if ($b.ECN) {
        if ($b.ECN.ToLower() -like "*disabled*") { & netsh int tcp set global ecncapability=disabled | Out-Null }
        else { & netsh int tcp set global ecncapability=enabled | Out-Null }
    }
    if ($b.RSS) {
        if ($b.RSS.ToLower() -like "*enabled*") { & netsh int tcp set global rss=enabled | Out-Null }
        else { & netsh int tcp set global rss=disabled | Out-Null }
    }
    if ($b.Timestamps) {
        if ($b.Timestamps.ToLower() -like "*disabled*") { & netsh int tcp set global timestamps=disabled | Out-Null }
        else { & netsh int tcp set global timestamps=enabled | Out-Null }
    }
    if ($b.InitialRto) {
        $num = ($b.InitialRto -replace '[^\d]','')
        if ($num) { & netsh int tcp set global initialRto=$num | Out-Null }
    }

    if ($b.DnsIfIndex -ge 0 -and $b.DnsServers) {
        try { Set-DnsClientServerAddress -InterfaceIndex ([int]$b.DnsIfIndex) -ServerAddresses ($b.DnsServers -split ',') } catch {}
    }

    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpTimedWaitDelay" "REG_DWORD" $b.TcpTimedWaitDelay
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "MaxUserPort" "REG_DWORD" $b.MaxUserPort
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpMaxDataRetransmissions" "REG_DWORD" $b.TcpMaxDataRetransmissions
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "Tcp1323Opts" "REG_DWORD" $b.Tcp1323Opts

    Restore-Reg "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NetworkThrottlingIndex" "REG_DWORD" $b.NetworkThrottlingIndex
    Restore-Reg "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness" "REG_DWORD" $b.SystemResponsiveness

    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" "KeyboardDataQueueSize" "REG_DWORD" $b.KeyboardDataQueueSize
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" "MouseDataQueueSize" "REG_DWORD" $b.MouseDataQueueSize
    Restore-Reg "HKCU:\Control Panel\Keyboard" "HKCU\Control Panel\Keyboard" "KeyboardDelay" "REG_SZ" $b.KeyboardDelay
    Restore-Reg "HKCU:\Control Panel\Keyboard" "HKCU\Control Panel\Keyboard" "KeyboardSpeed" "REG_SZ" $b.KeyboardSpeed
    Restore-Reg "HKCU:\Control Panel\Mouse" "HKCU\Control Panel\Mouse" "MouseSpeed" "REG_SZ" $b.MouseSpeed
    Restore-Reg "HKCU:\Control Panel\Mouse" "HKCU\Control Panel\Mouse" "MouseThreshold1" "REG_SZ" $b.MouseThreshold1
    Restore-Reg "HKCU:\Control Panel\Mouse" "HKCU\Control Panel\Mouse" "MouseThreshold2" "REG_SZ" $b.MouseThreshold2
    Restore-Reg "HKCU:\Control Panel\Desktop" "HKCU\Control Panel\Desktop" "MenuShowDelay" "REG_SZ" $b.MenuShowDelay
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Control" "HKLM\SYSTEM\CurrentControlSet\Control" "WaitToKillServiceTimeout" "REG_SZ" $b.WaitToKillServiceTimeout
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "HiberbootEnabled" "REG_DWORD" $b.HiberbootEnabled
    Restore-Reg "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "SearchOrderConfig" "REG_DWORD" $b.SearchOrderConfig
    Restore-Reg "HKLM:\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR" "HKLM\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR" "value" "REG_DWORD" $b.GameDVR
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "ForceIdle" "REG_DWORD" $b.ForceIdle
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "IdleUsbSelectiveSuspend" "REG_DWORD" $b.IdleUsbSelectiveSuspend
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "SelectiveSuspendEnabled" "REG_DWORD" $b.SelectiveSuspendEnabled
    Restore-Reg "HKLM:\SYSTEM\CurrentControlSet\Services\USB" "HKLM\SYSTEM\CurrentControlSet\Services\USB" "DisableSelectiveSuspend" "REG_DWORD" $b.DisableSelectiveSuspend

    Restore-Reg "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched" "HKLM\SOFTWARE\Policies\Microsoft\Windows\Psched" "NonBestEffortLimit" "REG_DWORD" $b.Policy_NonBestEffortLimit
    Restore-Reg "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" "HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" "DODownloadMode" "REG_DWORD" $b.Policy_DODownloadMode
    Restore-Reg "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" "HKLM\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" "LetAppsRunInBackground" "REG_DWORD" $b.Policy_LetAppsRunInBackground

    if ($b.SysMainStopped -eq $true) { & sc.exe stop sysmain | Out-Null } else { & sc.exe start sysmain | Out-Null }
    & gpupdate /force | Out-Null
    return $true
}

function Apply-UltraProfile {
    Save-Backup

    # Merged, stable profile from uploaded cmd/reg + requested policy settings
    & netsh int tcp set global autotuninglevel=normal | Out-Null
    & netsh int tcp set global ecncapability=disabled | Out-Null
    & netsh int tcp set global rss=enabled | Out-Null
    & netsh int tcp set global timestamps=disabled | Out-Null
    & netsh int tcp set global initialRto=2000 | Out-Null
    & netsh int tcp set global chimney=disabled | Out-Null
    & netsh int tcp set heuristics disabled | Out-Null

Remove-Item -Path "$env:TEMP\*" -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -Path "C:\Windows\Temp\*" -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -Path "C:\Windows\Prefetch\*" -Recurse -Force -ErrorAction SilentlyContinue

    try {
        $a = Get-NetAdapter | Where-Object {$_.Status -eq 'Up'} | Select-Object -First 1
        if ($a) { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ServerAddresses ("8.8.8.8","8.8.4.4") }
    } catch {}

    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpTimedWaitDelay" "REG_DWORD" "30"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "MaxUserPort" "REG_DWORD" "65534"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpMaxDataRetransmissions" "REG_DWORD" "3"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "Tcp1323Opts" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "DefaultTTL" "REG_DWORD" "64"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnablePMTUDiscovery" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnablePMTUBHDetect" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnableTCPA" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnableDCA" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnableRSS" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "EnableWsd" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "DisableTaskOffload" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpMaxDupAcks" "REG_DWORD" "2"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "SackOpts" "REG_DWORD" "1"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpFinWait2Delay" "REG_DWORD" "30"

    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NetworkThrottlingIndex" "REG_DWORD" "4294967295"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" "GPU Priority" "REG_DWORD" "8"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" "Priority" "REG_DWORD" "6"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" "Scheduling Category" "REG_SZ" "High"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" "SFIO Priority" "REG_SZ" "High"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR" "value" "REG_DWORD" "0"

    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" "KeyboardDataQueueSize" "REG_DWORD" "16"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" "MouseDataQueueSize" "REG_DWORD" "16"
    AddOrSet-Reg "HKCU\Control Panel\Keyboard" "KeyboardDelay" "REG_SZ" "0"
    AddOrSet-Reg "HKCU\Control Panel\Keyboard" "KeyboardSpeed" "REG_SZ" "31"
    AddOrSet-Reg "HKCU\Control Panel\Keyboard" "InitialKeyboardIndicators" "REG_SZ" "2"
    AddOrSet-Reg "HKCU\Control Panel\Accessibility\StickyKeys" "Flags" "REG_SZ" "506"
    AddOrSet-Reg "HKCU\Control Panel\Accessibility\Keyboard Response" "Flags" "REG_SZ" "122"

    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseSpeed" "REG_SZ" "0"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseThreshold1" "REG_SZ" "0"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseThreshold2" "REG_SZ" "0"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseSensitivity" "REG_SZ" "10"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "DoubleClickSpeed" "REG_SZ" "200"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "DoubleClickHeight" "REG_SZ" "4"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "DoubleClickWidth" "REG_SZ" "4"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseHoverTime" "REG_SZ" "49"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseHoverWidth" "REG_SZ" "1"
    AddOrSet-Reg "HKCU\Control Panel\Mouse" "MouseHoverHeight" "REG_SZ" "4"

    AddOrSet-Reg "HKCU\Control Panel\Desktop" "MenuShowDelay" "REG_SZ" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Control" "WaitToKillServiceTimeout" "REG_SZ" "2000"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "HiberbootEnabled" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "SearchOrderConfig" "REG_DWORD" "0"

    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "ForceIdle" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "IdleUsbSelectiveSuspend" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\HidUsb\Parameters" "SelectiveSuspendEnabled" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SYSTEM\CurrentControlSet\Services\USB" "DisableSelectiveSuspend" "REG_DWORD" "1"

    # Requested policy layer
    AddOrSet-Reg "HKLM\SOFTWARE\Policies\Microsoft\Windows\Psched" "NonBestEffortLimit" "REG_DWORD" "0"
    AddOrSet-Reg "HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" "DODownloadMode" "REG_DWORD" "100"
    AddOrSet-Reg "HKLM\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" "LetAppsRunInBackground" "REG_DWORD" "2"

    & sc.exe stop sysmain | Out-Null
    & gpupdate /force | Out-Null
    return $true
}

$form.Add_FormClosing({
    try { Clear-History; Remove-Item -Path ((Get-PSReadLineOption -ErrorAction SilentlyContinue).HistorySavePath) -Force -ErrorAction SilentlyContinue } catch {}
})

function DotColor([bool]$ok) {
    if ($ok) { return [System.Drawing.Color]::LimeGreen } else { return [System.Drawing.Color]::IndianRed }
}

function Verify-Profile {
    $v = [ordered]@{
        AutoTuning = Get-NetshValue "Receive Window Auto-Tuning Level"
        ECN = Get-NetshValue "ECN Capability"
        RSS = Get-NetshValue "Receive-Side Scaling State"
        InitialRto = Get-NetshValue "Initial RTO"
        TcpTimedWaitDelay = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpTimedWaitDelay")
        MaxUserPort = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "MaxUserPort")
        TcpMaxDataRetransmissions = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "TcpMaxDataRetransmissions")
        Tcp1323Opts = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" "Tcp1323Opts")
        KeyboardDataQueueSize = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" "KeyboardDataQueueSize")
        MouseDataQueueSize = [string](Get-RegValue "HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" "MouseDataQueueSize")
        KeyboardDelay = [string](Get-RegValue "HKCU:\Control Panel\Keyboard" "KeyboardDelay")
        KeyboardSpeed = [string](Get-RegValue "HKCU:\Control Panel\Keyboard" "KeyboardSpeed")
        MouseSpeed = [string](Get-RegValue "HKCU:\Control Panel\Mouse" "MouseSpeed")
        NetworkThrottlingIndex = [string](Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NetworkThrottlingIndex")
        SystemResponsiveness = [string](Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness")
        SearchOrderConfig = [string](Get-RegValue "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "SearchOrderConfig")
        SysMain = if (Get-ServiceStopped "sysmain") { "STOPPED" } else { "RUNNING / OTHER" }
        Policy_QoS = [string](Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched" "NonBestEffortLimit")
        Policy_DO = [string](Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization" "DODownloadMode")
        Policy_BGApps = [string](Get-RegValue "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy" "LetAppsRunInBackground")
    }
    return $v
}




function Get-BGImage {
    $b64 = @"

"@
    try {
        $bytes = [Convert]::FromBase64String(($b64 -replace '\s',''))
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        $img = [System.Drawing.Image]::FromStream($ms)
        $script:BGStream = $ms
        return $img
    } catch { return $null }
}

function New-UiFont {
    param([float]$Size = 10,[bool]$Bold = $false)
    $style = [System.Drawing.FontStyle]::Regular
    if ($Bold) { $style = [System.Drawing.FontStyle]::Bold }
    return New-Object System.Drawing.Font -ArgumentList "Segoe UI", $Size, $style
}

function New-Label {
    param(
        [string]$Text,[int]$X,[int]$Y,[int]$W,[int]$H,
        [float]$Size = 10,[bool]$Bold = $false,
        [System.Drawing.Color]$Color = $null
    )
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $Text
    $l.Location = New-Object System.Drawing.Point -ArgumentList $X,$Y
    $l.Size = New-Object System.Drawing.Size -ArgumentList $W,$H
    $l.Font = New-UiFont $Size $Bold
    if ($Color -eq $null) { $Color = [System.Drawing.Color]::White }
    $l.ForeColor = $Color
    $l.BackColor = [System.Drawing.Color]::Transparent
    $l.UseCompatibleTextRendering = $true
    return $l
}

function New-Panel {
    param([int]$X,[int]$Y,[int]$W,[int]$H,[int]$Alpha = 175)
    $p = New-Object System.Windows.Forms.Panel
    $p.Location = New-Object System.Drawing.Point -ArgumentList $X,$Y
    $p.Size = New-Object System.Drawing.Size -ArgumentList $W,$H
    $p.BackColor = [System.Drawing.Color]::FromArgb($Alpha,5,12,24)
    $p.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    return $p
}

function New-Button {
    param([string]$Text,[int]$X,[int]$Y,[int]$W,[int]$H,[bool]$Primary = $false)
    $b = New-Object System.Windows.Forms.Button
    $b.Text = $Text
    $b.Location = New-Object System.Drawing.Point -ArgumentList $X,$Y
    $b.Size = New-Object System.Drawing.Size -ArgumentList $W,$H
    $b.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $b.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(190,0,35)
    $b.FlatAppearance.BorderSize = 1
    if ($Primary) { $b.BackColor = [System.Drawing.Color]::FromArgb(150,0,28) }
    else { $b.BackColor = [System.Drawing.Color]::FromArgb(18,8,10) }
    $b.ForeColor = [System.Drawing.Color]::White
    $b.Font = New-UiFont 10 $true
    $b.UseCompatibleTextRendering = $true
    return $b
}

function New-MenuItem {
    param([string]$Icon,[string]$Text,[int]$Y,[bool]$Active = $false)
    $p = New-Object System.Windows.Forms.Panel
    $p.Location = New-Object System.Drawing.Point -ArgumentList 22,$Y
    $p.Size = New-Object System.Drawing.Size -ArgumentList 220,52
    if ($Active) {
        $p.BackColor = [System.Drawing.Color]::FromArgb(210,90,0,25)
        $p.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
    } else {
        $p.BackColor = [System.Drawing.Color]::Transparent
    }
    $i = New-Label $Icon 13 11 36 30 18 $false ([System.Drawing.Color]::FromArgb(190,0,35))
    $t = New-Label $Text 62 15 150 25 10 $false ([System.Drawing.Color]::White)
    $p.Controls.Add($i)
    $p.Controls.Add($t)
    return $p
}

function New-Card {
    param([string]$Icon,[string]$Title,[string]$Desc,[int]$X,[int]$Y)
    $p = New-Panel $X $Y 310 128 165
    $i = New-Label $Icon 22 28 52 54 27 $false ([System.Drawing.Color]::FromArgb(190,0,35))
    $t = New-Label $Title 100 26 190 25 11 $true ([System.Drawing.Color]::White)
    $d = New-Label $Desc 100 58 190 55 10 $false ([System.Drawing.Color]::Gainsboro)
    $p.Controls.Add($i)
    $p.Controls.Add($t)
    $p.Controls.Add($d)
    return $p
}

