$script:drag = $false
$script:start = New-Object System.Drawing.Point
$overlay.Add_MouseDown({
    if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
        $script:drag = $true
        $script:start = $_.Location
    }
})
$overlay.Add_MouseMove({
    if ($script:drag) {
        $p = [System.Windows.Forms.Cursor]::Position
        $form.Location = New-Object System.Drawing.Point -ArgumentList ($p.X - $script:start.X),($p.Y - $script:start.Y)
    }
})
$overlay.Add_MouseUp({ $script:drag = $false })

$applyBtn.Add_Click({
    $ready.Text = "Applying..."
    $form.Refresh()
    try {
        Apply-UltraProfile | Out-Null
        $ready.Text = "Ready"
        [System.Windows.Forms.MessageBox]::Show("Tuaperd Fanphu Ultra profile has been applied. Please restart your PC for best results.","Tuaperd Fanphu") | Out-Null
    } catch {
        $ready.Text = "Error"
        [System.Windows.Forms.MessageBox]::Show("Apply failed. Run as Administrator and try again.","Tuaperd Fanphu") | Out-Null
    }
})

$restoreBtn.Add_Click({
    $ready.Text = "Restoring..."
    $form.Refresh()
    $ok = Restore-Backup
    $ready.Text = "Ready"
    if($ok){
        [System.Windows.Forms.MessageBox]::Show("Previous settings have been restored.","Tuaperd Fanphu") | Out-Null
    } else {
        [System.Windows.Forms.MessageBox]::Show("No backup file was found.","Tuaperd Fanphu") | Out-Null
    }
})

$verifyBtn.Add_Click({
    $v = Verify-Profile
    $verText.Text = "AutoTuning: $($v.AutoTuning) | ECN: $($v.ECN) | RSS: $($v.RSS) | TCP: $($v.TcpTimedWaitDelay) | Input: $($v.KeyboardDataQueueSize)/$($v.MouseDataQueueSize) | GameDVR: $($v.GameDVR) | QoS: $($v.Policy_QoS) | DO: $($v.Policy_DO) | SysMain: $($v.SysMain)"
})

